const assetUrl=file=>`${file}?v=29`;
const $=s=>document.querySelector(s),grid=$('#grid'),filters=$('#filters'),dialog=$('#preview');
let active=0,shown=[],previewSet=[];
const categories=[...new Set(materials.map(m=>m.group))];
const labels=categories;
const help={'교사용 지도안':'차시별 2쪽 · 총 8쪽','수업 PPT':'현재 순서대로 1–37번','학생 워크북':'표지·목차 포함 10쪽','교사용 워크북':'학생용과 같은 쪽 순서 · 예시 답안과 지도 도움말','참고자료':'카드·평가 기록 · 실천 운영·교육과정·평가 도움말'};
categories.forEach((group,index)=>{const b=document.createElement('button');b.innerHTML=`<span>${labels[index]}</span><span class="tab-count">${materials.filter(m=>m.group===group).length}</span>`;b.setAttribute('aria-pressed',index===0);b.onclick=()=>{filters.querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));select(group)};filters.append(b)});
function select(group){shown=materials.filter(m=>m.group===group);$('#groupHelp').textContent=help[group]||'';render()}
function render(){grid.replaceChildren();$('#count').textContent=`${shown.length}장`;grid.classList.toggle('slides',shown[0]?.group==='수업 PPT');shown.forEach((m,i)=>{const card=document.createElement('article');card.className='card';const type=m.file.endsWith('.jpg')?'JPG':'PNG';card.innerHTML=`<button class="thumb" aria-label="${m.title} 미리보기"><img src="${assetUrl(m.file)}" alt="${m.title}" loading="lazy" width="${m.width||1055}" height="${m.height||1491}"></button><div class="info">${m.lesson?`<p class="lesson-label">${m.lesson}차시</p>`:''}<h3>${m.title}</h3><div class="actions"><button>미리보기</button></div></div>`;card.querySelectorAll('button').forEach(b=>b.onclick=()=>{previewSet=shown.slice();open(i)});grid.append(card)})}
function open(i){if(i<0||i>=previewSet.length)return;active=i;const m=previewSet[i];$('#previewTitle').textContent=m.title;$('#large').src=assetUrl(m.file);$('#large').alt=m.title;dialog.classList.toggle('landscape',m.group==='수업 PPT');$('#position').textContent=`${i+1} / ${previewSet.length}`;$('#prev').disabled=i===0;$('#next').disabled=i===previewSet.length-1;if(!dialog.open)dialog.showModal();$('.image-wrap').scrollTop=0}
$('#close').onclick=()=>dialog.close();$('#prev').onclick=()=>open(active-1);$('#next').onclick=()=>open(active+1);dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});dialog.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();open(active-1)}if(e.key==='ArrowRight'){e.preventDefault();open(active+1)}});select(categories[0]);
const crcTable=Array.from({length:256},(_,n)=>{for(let k=0;k<8;k++)n=n&1?0xedb88320^(n>>>1):n>>>1;return n>>>0});
function crc32(bytes){let c=0xffffffff;for(const b of bytes)c=crcTable[(c^b)&255]^(c>>>8);return(c^0xffffffff)>>>0}
function zipHeader(size,values){const a=new Uint8Array(size),v=new DataView(a.buffer);for(const[o,n,w]of values)w===2?v.setUint16(o,n,true):v.setUint32(o,n,true);return a}
async function bundle(items,filename,button,status){button.disabled=true;try{const parts=[],central=[];let offset=0;for(let i=0;i<items.length;i++){status.textContent=`자료 준비 중 ${i+1} / ${items.length}`;const m=items[i],r=await fetch(assetUrl(m.file));if(!r.ok)throw Error('download');const data=new Uint8Array(await r.arrayBuffer()),name=new TextEncoder().encode(m.name),crc=crc32(data),n=data.length;parts.push(zipHeader(30,[[0,0x04034b50,4],[4,20,2],[6,0x800,2],[14,crc,4],[18,n,4],[22,n,4],[26,name.length,2]]),name,data);central.push(zipHeader(46,[[0,0x02014b50,4],[4,20,2],[6,20,2],[8,0x800,2],[16,crc,4],[20,n,4],[24,n,4],[28,name.length,2],[42,offset,4]]),name);offset+=30+name.length+n}const centralSize=central.reduce((s,a)=>s+a.length,0);const end=zipHeader(22,[[0,0x06054b50,4],[8,items.length,2],[10,items.length,2],[12,centralSize,4],[16,offset,4]]);const url=URL.createObjectURL(new Blob([...parts,...central,end],{type:'application/zip'}));const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='다운로드가 시작됩니다.'}catch{status.textContent='자료를 받지 못했습니다. 잠시 후 다시 시도해 주세요.'}finally{button.disabled=false}}
$('#allDownload').onclick=()=>bundle([
 ...packages.map((p,i)=>({file:p.file,name:`문서/${i+1}_${p.title}.${p.format.toLowerCase()}`}))
],'HEAL-IT_수업꾸러미.zip',$('#allDownload'),$('#downloadStatus'));
